{
  "root_cause": "disk_exhaustion",
  "summary": "The incident was caused by disk space exhaustion on node api-3, which led to write failures and increased error rates. Disk usage on api-3 rose sharply from around 60% to over 100%, causing the application to fail writes due to no space left on device.",
  "onset_ts": "2026-03-17T09:37:00.000Z",
  "timeline": [
    {
      "statement": "Disk usage on api-3 started increasing sharply from 60.6% at 09:00 to 100.7% at 09:59.",
      "citations": [
        {
          "source": "metrics/disk.csv",
          "line": 2,
          "quote": "2026-03-17T09:00:00.000Z,60.6,44.2,46.4"
        },
        {
          "source": "metrics/disk.csv",
          "line": 61,
          "quote": "2026-03-17T09:59:00.000Z,100.7,44.1,46.3"
        }
      ]
    },
    {
      "statement": "The first alert for ApiWriteErrors firing was at 09:37, coinciding with rising disk usage.",
      "citations": [
        {
          "source": "alerts.jsonl",
          "line": 1,
          "quote": "{\"ts\":\"2026-03-17T09:37:00.000Z\",\"name\":\"ApiWriteErrors\",\"severity\":\"page\",\"state\":\"firing\"}"
        }
      ]
    },
    {
      "statement": "DiskSpaceCritical alert fired at 09:39, confirming disk exhaustion on api-3.",
      "citations": [
        {
          "source": "alerts.jsonl",
          "line": 2,
          "quote": "{\"ts\":\"2026-03-17T09:39:00.000Z\",\"name\":\"DiskSpaceCritical\",\"severity\":\"page\",\"state\":\"firing\"}"
        }
      ]
    },
    {
      "statement": "Application logs on api-3 show repeated errors 'write failed: no space left on device' starting at 09:34 and continuing through the incident.",
      "citations": [
        {
          "source": "logs/app.jsonl",
          "line": 1007,
          "quote": "\"msg\":\"write failed: no space left on device\",\"node\":\"api-3\""
        },
        {
          "source": "logs/app.jsonl",
          "line": 1090,
          "quote": "\"msg\":\"write failed: no space left on device\",\"node\":\"api-3\""
        }
      ]
    },
    {
      "statement": "Warnings about log rotation failing due to zero free bytes on api-3 also started at 09:34 and persisted.",
      "citations": [
        {
          "source": "logs/app.jsonl",
          "line": 1009,
          "quote": "\"msg\":\"log rotation failed\",\"node\":\"api-3\",\"free_bytes\":0"
        },
        {
          "source": "logs/app.jsonl",
          "line": 1100,
          "quote": "\"msg\":\"log rotation failed\",\"node\":\"api-3\",\"free_bytes\":0"
        }
      ]
    },
    {
      "statement": "HTTP error rate increased sharply from baseline ~0.002 to peaks above 0.04 starting at 09:34, consistent with write failures.",
      "citations": [
        {
          "source": "metrics/http.csv",
          "line": 36,
          "quote": "2026-03-17T09:34:00.000Z,44.58,186.88,0.0339,329"
        },
        {
          "source": "metrics/http.csv",
          "line": 60,
          "quote": "2026-03-17T09:58:00.000Z,42.15,254.6,0.0462,333"
        }
      ]
    }
  ],
  "evidence": [
    {
      "statement": "Disk usage on api-3 reached 100.7% at 09:59, which directly explains the 'no space left on device' errors and log rotation failures.",
      "citations": [
        {
          "source": "metrics/disk.csv",
          "line": 61,
          "quote": "2026-03-17T09:59:00.000Z,100.7,44.1,46.3"
        },
        {
          "source": "logs/app.jsonl",
          "line": 1007,
          "quote": "\"msg\":\"write failed: no space left on device\",\"node\":\"api-3\""
        }
      ]
    },
    {
      "statement": "The DiskSpaceCritical alert firing at 09:39 confirms the disk exhaustion condition on api-3.",
      "citations": [
        {
          "source": "alerts.jsonl",
          "line": 2,
          "quote": "{\"ts\":\"2026-03-17T09:39:00.000Z\",\"name\":\"DiskSpaceCritical\",\"severity\":\"page\",\"state\":\"firing\"}"
        }
      ]
    }
  ],
  "ruled_out": [
    {
      "statement": "Bad deploy regression is unlikely because there is no evidence of increased latency or error rate before disk usage rose; error rate increase coincides with disk exhaustion.",
      "citations": [
        {
          "source": "metrics/http.csv",
          "line": 2,
          "quote": "2026-03-17T09:00:00.000Z,38.58,186.21,0.0022,337"
        },
        {
          "source": "metrics/disk.csv",
          "line": 2,
          "quote": "2026-03-17T09:00:00.000Z,60.6,44.2,46.4"
        }
      ]
    },
    {
      "statement": "Config change is unlikely as the only config flag change was enabling debug_request_logging at 09:02, which did not cause immediate errors or disk usage increase.",
      "citations": [
        {
          "source": "changes.jsonl",
          "line": 1,
          "quote": "enabled on api-3 to chase a support ticket"
        },
        {
          "source": "metrics/disk.csv",
          "line": 4,
          "quote": "2026-03-17T09:02:00.000Z,61.4,43.7,46.4"
        }
      ]
    }
  ],
  "action_items": [
    "Implement disk usage monitoring with automated cleanup or alerting before critical thresholds are reached.",
    "Investigate root causes of disk space growth on api-3 to prevent recurrence.",
    "Improve log rotation reliability to avoid failures when disk space is low.",
    "Review capacity planning and increase disk size or optimize storage usage on api-3."
  ]
}
